CREATE TABLE "c_Activity" ("id" BIGINT NOT NULL, "a_Activity_activity_type" TEXT NOT NULL, "a_Activity_occurred_at" TIMESTAMP NOT NULL, "r_ContactActivities_source_id" BIGINT, "r_ContactActivities_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ContactActivities_source_dtype" IS NULL OR "r_ContactActivities_source_dtype" IN ('Contact','CustomerContact','Lead')), CHECK ((TRUE) OR "r_ContactActivities_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ContactActivities_source_id" IS NOT NULL));
CREATE TABLE "c_Contact" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Contact_email" TEXT, "a_CustomerContact_customer_since" DATE, "a_Lead_source" TEXT, "r_OrgContacts_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Contact','CustomerContact','Lead')), CHECK ((dtype IN ('Contact','CustomerContact','Lead')) OR "a_Contact_email" IS NULL), CHECK (NOT (dtype IN ('Contact','CustomerContact','Lead')) OR "a_Contact_email" IS NOT NULL), CHECK ((dtype IN ('CustomerContact')) OR "a_CustomerContact_customer_since" IS NULL), CHECK (NOT (dtype IN ('CustomerContact')) OR "a_CustomerContact_customer_since" IS NOT NULL), CHECK ((dtype IN ('Lead')) OR "a_Lead_source" IS NULL), CHECK (NOT (dtype IN ('Lead')) OR "a_Lead_source" IS NOT NULL), CHECK ((dtype IN ('Contact','CustomerContact','Lead')) OR "r_OrgContacts_source_id" IS NULL), CHECK (NOT (dtype IN ('Contact','CustomerContact','Lead')) OR "r_OrgContacts_source_id" IS NOT NULL));
CREATE TABLE "c_Opportunity" ("id" BIGINT NOT NULL, "a_Opportunity_amount" NUMERIC NOT NULL, "a_Opportunity_stage" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Organization" ("id" BIGINT NOT NULL, "a_Organization_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_ContactOpportunities" ("r_ContactOpportunities_source_id" BIGINT NOT NULL, "r_ContactOpportunities_source_dtype" TEXT NOT NULL, "r_ContactOpportunities_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ContactOpportunities_source_id", "r_ContactOpportunities_target_id"), UNIQUE ("r_ContactOpportunities_target_id"), CHECK ("r_ContactOpportunities_source_dtype" IS NULL OR "r_ContactOpportunities_source_dtype" IN ('Contact','CustomerContact','Lead')));
ALTER TABLE "c_Activity" ADD CONSTRAINT "fk_c_Activity_0" FOREIGN KEY ("r_ContactActivities_source_id", "r_ContactActivities_source_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Contact" ADD CONSTRAINT "fk_c_Contact_0" FOREIGN KEY ("r_OrgContacts_source_id") REFERENCES "c_Organization" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ContactOpportunities" ADD CONSTRAINT "fk_l_ContactOpportunities_0" FOREIGN KEY ("r_ContactOpportunities_source_id", "r_ContactOpportunities_source_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ContactOpportunities" ADD CONSTRAINT "fk_l_ContactOpportunities_1" FOREIGN KEY ("r_ContactOpportunities_target_id") REFERENCES "c_Opportunity" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_ContactOpportunities"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Opportunity" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ContactOpportunities" l WHERE l."r_ContactOpportunities_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ContactOpportunities'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ContactOpportunities_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Opportunity" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ContactOpportunities"();
CREATE CONSTRAINT TRIGGER "ct_ContactOpportunities_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ContactOpportunities" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ContactOpportunities"();